import{_ as i,c as e,o as s,aj as t,ak as n}from"./chunks/framework.C2N4vG9O.js";const g=JSON.parse('{"title":"常见问题解答","description":"Torch-RecHub 常见问题及故障排除指南","frontmatter":{"title":"常见问题解答","description":"Torch-RecHub 常见问题及故障排除指南"},"headers":[],"relativePath":"zh/community/faq.md","filePath":"zh/community/faq.md"}'),r={name:"zh/community/faq.md"};function h(l,a,o,d,p,c){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to “常见问题解答”">​</a></h1><h2 id="会推出-tensorflow-版本吗" tabindex="-1">会推出 TensorFlow 版本吗？ <a class="header-anchor" href="#会推出-tensorflow-版本吗" aria-label="Permalink to “会推出 TensorFlow 版本吗？”">​</a></h2><p>项目目前使用 PyTorch，暂无 TensorFlow 版本计划。</p><h2 id="为什么示例的-auc-很低或波动很大" tabindex="-1">为什么示例的 AUC 很低或波动很大？ <a class="header-anchor" href="#为什么示例的-auc-很低或波动很大" aria-label="Permalink to “为什么示例的 AUC 很低或波动很大？”">​</a></h2><p>仓库自带的数据只取了很小一部分，换几条验证记录就可能让 AUC 明显变化。第一次跑示例，先确认训练结束、预测有输出。要比较两个模型，再换用完整数据集，并让两个模型共用同一份训练、验证和测试划分。<a href="https://github.com/datawhalechina/torch-rechub/tree/main/examples/ranking" target="_blank" rel="noreferrer">排序数据说明</a> · <a href="https://github.com/datawhalechina/torch-rechub/tree/main/examples/matching" target="_blank" rel="noreferrer">召回数据说明</a></p><h2 id="annoy-在-windows-上安装失败怎么办" tabindex="-1">Annoy 在 Windows 上安装失败怎么办？ <a class="header-anchor" href="#annoy-在-windows-上安装失败怎么办" aria-label="Permalink to “Annoy 在 Windows 上安装失败怎么办？”">​</a></h2><p>先用当前 Python 环境安装 Annoy 依赖。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;torch-rechub[annoy]&quot;</span></span></code></pre></div><p>如果没有适合当前 Python 版本的预编译包，pip 会从源码编译 Annoy。出现 <code>Microsoft Visual C++ 14.0 or greater is required</code> 时，安装 Microsoft C++ Build Tools，重新打开终端后再运行上面的命令。<a href="https://visualstudio.microsoft.com/visual-cpp-build-tools/" target="_blank" rel="noreferrer">Microsoft C++ Build Tools</a></p><p><img src="'+n+`" alt="Annoy 编译环境报错" title="Annoy 编译环境报错"></p><h2 id="只使用-annoy-需要安装哪些依赖" tabindex="-1">只使用 Annoy 需要安装哪些依赖？ <a class="header-anchor" href="#只使用-annoy-需要安装哪些依赖" aria-label="Permalink to “只使用 Annoy 需要安装哪些依赖？”">​</a></h2><p>运行上面的安装命令就够了。<code>builder_factory(&quot;annoy&quot;, d=64)</code> 使用本地 Annoy 索引，只有选用 Milvus 才需要连接服务端。</p><h2 id="为什么-fit-时提示模型保存路径不存在" tabindex="-1">为什么 <code>fit()</code> 时提示模型保存路径不存在？ <a class="header-anchor" href="#为什么-fit-时提示模型保存路径不存在" aria-label="Permalink to “为什么 fit() 时提示模型保存路径不存在？”">​</a></h2><p>用 <code>CTRTrainer</code>、<code>MatchTrainer</code> 或 <code>MTLTrainer</code> 时，先创建 <code>model_path</code> 指向的目录。下面把排序模型保存在 <code>saved/deepfm</code>。</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> torch_rechub.trainers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CTRTrainer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.makedirs(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;saved/deepfm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">exist_ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trainer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CTRTrainer(model, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model_path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;saved/deepfm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trainer.fit(train_dataloader, val_dataloader)</span></span></code></pre></div><h2 id="为什么从不同目录运行示例会提示数据文件不存在" tabindex="-1">为什么从不同目录运行示例会提示数据文件不存在？ <a class="header-anchor" href="#为什么从不同目录运行示例会提示数据文件不存在" aria-label="Permalink to “为什么从不同目录运行示例会提示数据文件不存在？”">​</a></h2><p>有些脚本把数据写成 <code>./data/...</code>。Python 会从启动命令时的工作目录找这个文件。比如运行排序示例前，先进入 <code>examples/ranking</code>。如果脚本提供 <code>--dataset_path</code>，也可以直接传数据的绝对路径。</p><h2 id="同一批-feature-可以同时传给多个模型吗" tabindex="-1">同一批 Feature 可以同时传给多个模型吗？ <a class="header-anchor" href="#同一批-feature-可以同时传给多个模型吗" aria-label="Permalink to “同一批 Feature 可以同时传给多个模型吗？”">​</a></h2><p>独立训练两个模型时，两个模型可以读同名的 <code>item_id</code> 列，各自新建 <code>SparseFeature</code> 或 <code>SequenceFeature</code> 即可。如果直接把同一个 Feature 对象传两次，两个模型会拿到同一张已经创建的嵌入表。在一个模型里希望历史物品和目标物品共用这张表时，用 <code>shared_with</code> 指定对应的物品特征。<a href="/torch-rechub/zh/core/features.html#feature-实例与-embedding-所有权">特征与嵌入表</a></p>`,19)])])}const u=i(r,[["render",h]]);export{g as __pageData,u as default};
